export type StringKey = keyof typeof STRINGS;

/** Text for `key`, with each `{placeholder}` replaced by the matching value. */
export function t(key: StringKey, values: Record<string, string | number> = {}): string {
  return STRINGS[key].replace(/\{(\w+)\}/g, (whole, name: string) =>
    name in values ? String(values[name]) : whole,
  );
}

/**
 * Keys ending in `.short` that are not Explorer wordings: names and "not met" lines from before the convention.
 * Every other `<key>.short` is the Explorer wording of `<key>`.
 */
export const NOT_SHORT_VARIANTS: readonly string[] = [
  'review.short',
  'report.short',
  'finding.orbit.short',
  'finding.payload.short',
  'finding.power.short',
  'finding.comms.short',
  'finding.time.short',
  'launchSite.capeCanaveral.short',
  'launchSite.wallops.short',
  'launchSite.kennedy39A.short',
  'launchSite.kennedy39B.short',
];

/** The Explorer wording of `key` (`<key>.short`), if it has one. */
export function shortKey(key: StringKey): StringKey | null {
  const short = `${key}.short`;
  return short in STRINGS && !NOT_SHORT_VARIANTS.includes(short) ? (short as StringKey) : null;
}

/** Text for `key` in a game mode: Explorer (`explorer` true) reads `<key>.short` when it exists, else `key`. */
export function textFor(key: StringKey, explorer: boolean, values: Record<string, string | number> = {}): string {
  const short = explorer ? shortKey(key) : null;
  return t(short ?? key, values);
}
